// Descriptor-driven mapping and synthesis (fm-qjcs). A model at a different resolution and W+ layer count, AFHQ cat
// 512 (16 x 512, 15 noise planes), runs through the package's CPU generator with every dimension read from its
// descriptor. It is checked against an independent reference: the pinned upstream implementation
// (NVlabs/stylegan2-ada-pytorch) running the original checkpoint, regenerated by test/vectors/afhq-cat-512/make-reference.py
// and held to the model's own declared tolerance (raw 1e-3, RGB 1; model-conv models.py). The descriptor and the
// reference's provenance and digests are committed (test/vectors/afhq-cat-512/reference.json). The weights and
// reference arrays are not committed. Where they are absent the model cases report untested. Each unsupported field
// is rejected with a typed DescriptorUnsupported naming it, before any byte is read.
// FFHQ's kernels at its descriptor's side stay the candidate's, character for character (routes.test.ts).
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';
import * as onnx from 'onnxruntime-web';
import {
  AFHQ_CAT_512_DESCRIPTOR,
  FFHQ_1024_DESCRIPTOR,
  type ModelDescriptor,
} from '../../src/contracts/descriptor.ts';
import { loadCpuGenerator } from '../../src/engine/adapters/cpu.ts';
import { loadDirectWebGpuGenerator } from '../../src/engine/adapters/direct-webgpu.ts';
import type { GeneratorManifest } from '../../src/engine/adapters/generator.ts';
import type { OrtModule } from '../../src/engine/adapters/ort.ts';
import { loadOrtWebGpuGenerator } from '../../src/engine/adapters/ort-webgpu.ts';
import { engineError } from '../../src/engine/engine.ts';
import { FFHQ_LATENT, FFHQ_SIDE, inputLatent, toRgba8 } from '../../src/engine/identity.ts';
import {
  checkManifest,
  DescriptorUnsupported,
  engineGeometry,
  type EngineKind,
} from '../../src/engine/model.ts';
import { acquiredManifest, runtimeReader } from './support/runtime.ts';

const HERE = fileURLToPath(new URL('.', import.meta.url));
const REPO = join(HERE, '../../../../');
const PROVENANCE = JSON.parse(
  readFileSync(join(HERE, '../vectors/afhq-cat-512/reference.json'), 'utf8'),
) as {
  checkpointSha256: string;
  implementation: string;
  truncation: { psi: number; cutoff: number };
  tolerance: { rawFloat: number; rgb: number };
  cases: {
    seed: number;
    z: { file: string; sha256: string; size: number };
    w: { file: string; sha256: string; size: number; shape: number[] };
    raw: { file: string; sha256: string; size: number; shape: number[] };
  }[];
  converted: { manifestSha256: string };
};
const MODEL = process.env['FACEMORPH_AFHQ_CAT'] ?? join(REPO, 'packages/model-conv/out/afhqcat');
const REFERENCE = join(MODEL, 'reference');
const sha256 = (b: Uint8Array) => createHash('sha256').update(b).digest('hex');
const UNTESTED_AFHQ = `untested: the converted AFHQ cat model and its upstream reference are not at ${MODEL} (packages/model-conv/docs/usage.md, then test/vectors/afhq-cat-512/make-reference.py)`;

/** The converted model, if it is the one the reference provenance names. */
function afhq(): { manifest: GeneratorManifest; sha256: string } | null {
  const path = join(MODEL, 'manifest.json');
  if (!existsSync(path) || !existsSync(join(REFERENCE, 'reference.json'))) return null;
  const bytes = readFileSync(path);
  assert.equal(
    sha256(bytes),
    PROVENANCE.converted.manifestSha256,
    'the converted manifest the provenance names',
  );
  return { manifest: JSON.parse(bytes.toString('utf8')), sha256: sha256(bytes) };
}
const f32 = (file: string, expected: { sha256: string; size: number }) => {
  const b = readFileSync(join(REFERENCE, file));
  assert.equal(b.length, expected.size, file);
  assert.equal(sha256(b), expected.sha256, `${file} matches the committed reference digest`);
  return new Float32Array(b.buffer.slice(b.byteOffset, b.byteOffset + b.length));
};
const maxAbs = (a: Float32Array, b: Float32Array) => {
  assert.equal(a.length, b.length);
  let m = 0;
  for (let i = 0; i < a.length; i++) m = Math.max(m, Math.abs((a[i] as number) - (b[i] as number)));
  return m;
};

const ort = onnx as unknown as OrtModule;
ort.env.wasm.numThreads = 1;
const ids = (n: number) => ({ requestId: `afhq${n}`, inputRevision: n, attemptId: 0 });

test(
  'AFHQ cat 512 (16 W+ layers) maps and synthesizes through the descriptor within its own declared tolerance of the upstream reference',
  { timeout: 900_000 },
  async (t) => {
    const model = afhq();
    if (!model) return t.skip(UNTESTED_AFHQ);
    const reads: string[] = [];
    const g = await loadCpuGenerator({
      reader: runtimeReader(MODEL, reads),
      manifest: model.manifest,
      manifestSha256: model.sha256,
      ort: async () => ort,
      descriptor: AFHQ_CAT_512_DESCRIPTOR,
    });
    t.after(() => g.dispose());
    assert.deepEqual(g.latent, { zLength: 512, layers: 16, width: 512 });
    assert.deepEqual(g.image, { width: 512, height: 512 });
    assert.equal(g.geometry.noise.length, 15);
    const { rawFloat, rgb } = PROVENANCE.tolerance;
    const truncation = PROVENANCE.truncation;
    for (const c of PROVENANCE.cases) {
      const z = f32(c.z.file, c.z);
      // The package's seed latent is NumPy's legacy RandomState(seed).randn, bit for bit.
      const input = inputLatent('seed', String(c.seed), g.latent);
      assert.deepEqual(input.z, z, `seed ${c.seed}: z equals NumPy RandomState(${c.seed}).randn`);
      const mapped = await g.map({ ids: ids(c.seed), z: input.z, truncation });
      assert.deepEqual(mapped.wPlus.shape, [16, 512]);
      const wError = maxAbs(mapped.wPlus.values, f32(c.w.file, c.w));
      const face = await g.synthesize({
        ids: ids(c.seed + 10),
        wPlus: mapped.wPlus,
        output: 'rgba-and-raw-float',
      });
      assert.deepEqual([face.width, face.height, face.rgba.length], [512, 512, 512 * 512 * 4]);
      const reference = f32(c.raw.file, c.raw);
      const rawError = maxAbs(face.rawFloat as Float32Array, reference);
      const expected = toRgba8(reference, 512, 512);
      let rgbError = 0;
      for (let i = 0; i < expected.length; i++)
        rgbError = Math.max(rgbError, Math.abs((face.rgba[i] as number) - (expected[i] as number)));
      t.diagnostic(
        `seed ${c.seed}: max |W+| error ${wError.toExponential(2)}, max raw error ${rawError.toExponential(2)}, max RGB ${rgbError} (declared raw ${rawFloat}, RGB ${rgb}; ${PROVENANCE.implementation})`,
      );
      assert.ok(wError <= rawFloat, `seed ${c.seed}: W+ within ${rawFloat}`);
      assert.ok(rawError <= rawFloat, `seed ${c.seed}: raw output within ${rawFloat}`);
      assert.ok(rgbError <= rgb, `seed ${c.seed}: RGB within ${rgb}`);
    }
    // The non-face model never touches a detector or the FFHQ e4e: nothing outside its own manifest was read.
    const own = new Set(
      [
        model.manifest.mapping,
        model.manifest.synthesis,
        model.manifest.average,
        ...model.manifest.noise,
      ].map((a) => a.sha256),
    );
    assert.ok(
      reads.length > 0 && reads.every((s) => own.has(s)),
      'only the AFHQ manifest assets were read',
    );
    const encoder = FFHQ_1024_DESCRIPTOR.photoEncoder!;
    assert.ok(!reads.includes(encoder.sourceSha256) && !reads.includes(encoder.detector.sha256));
  },
);

const unsupported = (
  mutate: (d: Record<string, unknown>) => void,
  field: string,
  code: 'invalid' | 'unsupported' | 'inconsistent',
  engine?: EngineKind,
  base: ModelDescriptor = AFHQ_CAT_512_DESCRIPTOR,
) => {
  const d = structuredClone(base) as unknown as Record<string, unknown>;
  mutate(d);
  assert.throws(
    () => engineGeometry(d, engine),
    (e: unknown) => {
      assert.ok(e instanceof DescriptorUnsupported, String(e));
      assert.equal(e.field, field);
      assert.equal(e.code, code);
      assert.ok(
        e.message.startsWith(field + ': ') && e.message.length > field.length + 10,
        e.message,
      );
      assert.equal(engineError(e).code, 'unsupported');
      return true;
    },
  );
};

test('each unsupported descriptor field is a descriptive typed rejection naming it', () => {
  // Supported: both qualified geometries.
  assert.deepEqual(engineGeometry(FFHQ_1024_DESCRIPTOR).latent, FFHQ_LATENT);
  assert.deepEqual(
    [
      engineGeometry(AFHQ_CAT_512_DESCRIPTOR).latent.layers,
      engineGeometry(AFHQ_CAT_512_DESCRIPTOR).width,
    ],
    [16, 512],
  );
  // Fields the engine does not run.
  unsupported(
    (d) => (d.conditioning = { kind: 'class', classes: 10 }),
    '$.conditioning',
    'unsupported',
  );
  unsupported(
    (d) => ((d.output as { shape: number[] }).shape = [1, 1, 512, 512]),
    '$.output.shape[1]',
    'unsupported',
  );
  unsupported(
    (d) => ((d.output as { range: number[] }).range = [0, 1]),
    '$.output.range',
    'unsupported',
  );
  unsupported(
    (d) => ((d.truncation as { cutoff: number }).cutoff = 17),
    '$.truncation.cutoff',
    'unsupported',
  );
  // Engines with kernels built for one checkpoint refuse any other.
  for (const engine of ['ort-webgpu', 'direct-webgpu'] as const)
    unsupported(() => {}, '$.identity.modelSha256', 'unsupported', engine);
  assert.equal(engineGeometry(FFHQ_1024_DESCRIPTOR, 'direct-webgpu').width, FFHQ_SIDE);
  // Fields the contract itself rejects (fm-z5wy's validation), named the same way.
  unsupported((d) => ((d.output as { layout: string }).layout = 'nhwc'), '$.output', 'invalid');
  unsupported((d) => ((d.noise as { mode: string }).mode = 'random'), '$.noise', 'invalid');
  unsupported((d) => (d.architecture = 'stylegan3'), '$.architecture', 'invalid');
  unsupported(
    (d) => ((d.latent as { layers: number }).layers = 18),
    '$.latent.layers',
    'inconsistent',
  );
  unsupported(
    (d) => (d.photoEncoder = FFHQ_1024_DESCRIPTOR.photoEncoder),
    '$.photoEncoder',
    'inconsistent',
  );
});

test('a manifest of another model is inconsistent with the descriptor, and is refused before any read or probe', async () => {
  const ffhq = acquiredManifest();
  const manifest = (ffhq?.manifest ?? {
    modelSourceSha256: FFHQ_1024_DESCRIPTOR.identity.modelSha256,
    noiseSha256: FFHQ_1024_DESCRIPTOR.identity.noiseSha256,
    noise: FFHQ_1024_DESCRIPTOR.noise.planes,
  }) as unknown as GeneratorManifest & { webgpu: never; webgl: never };
  checkManifest(FFHQ_1024_DESCRIPTOR, manifest);
  assert.throws(
    () => checkManifest(AFHQ_CAT_512_DESCRIPTOR, manifest),
    (e: unknown) => e instanceof DescriptorUnsupported && e.field === '$.identity.modelSha256',
  );
  assert.throws(
    () =>
      checkManifest(FFHQ_1024_DESCRIPTOR, {
        ...manifest,
        noise: manifest.noise.map((n, i) => (i === 3 ? { ...n, shape: [8, 8] } : n)),
      }),
    (e: unknown) => e instanceof DescriptorUnsupported && e.field === '$.noise.planes[3]',
  );
  const reads: string[] = [];
  const reader = {
    allowRepair: false as const,
    read: async (a: { sha256: string }) => (
      reads.push(a.sha256),
      { ok: false as const, error: { code: 'cache-miss', message: 'not read' } }
    ),
  };
  let probes = 0;
  const gpu = { requestAdapter: async () => (probes++, null) } as unknown as GPU;
  const common = {
    reader,
    manifest,
    manifestSha256: '0'.repeat(64),
    descriptor: AFHQ_CAT_512_DESCRIPTOR,
  };
  await assert.rejects(
    loadCpuGenerator({ ...common, ort: async () => ort }),
    DescriptorUnsupported,
  );
  await assert.rejects(
    loadOrtWebGpuGenerator({ ...common, gpu, host: null as never, cpuOrt: async () => ort }),
    DescriptorUnsupported,
  );
  await assert.rejects(
    loadDirectWebGpuGenerator({ ...common, gpu, cpuOrt: async () => ort }),
    DescriptorUnsupported,
  );
  assert.deepEqual([reads.length, probes], [0, 0], 'no byte read and no adapter probed');
});
